#include "stdafx.h"#include "..\MnemoWnd.h"#include "Queue.h"#include "..\Lang.h"#include "..\SocketClient.h"//  enum eDataType  {  DataBool,   DataInt,  DataDouble  };  enum eGasLiquidType  {	  GasLiquiedNone,	  GasLiquiedGas,	  GasLiquiedLiquied,      GasLiquiedGasLiquied  };//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структура работы с задвижкойtypedef struct : public SPROLOZ  {  bool bValue;  int nValue;  double dValue;  eDataType dataType;  char szName[64];  char szParam[64];  int nType;  COLORREF colorLevel;  COLORREF colorBkg;  COLORREF colorTrans;  double WorkMin,WorkMax;  eGasLiquidType gasType;  char szView[64];  } Queue_DataSH;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void PaintTransparentLevel(HDC hDC, Queue_DataSH* p, RECT& rc,COLORREF& clr, double& dValue, bool bOrange){	dValue = max( dValue, p->WorkMin );	dValue = min( dValue, p->WorkMax );	if (bOrange)	{		clr=p->colorBkg;		if ( ::GetMnemoStyle() & MNEMO_EDIT )			clr=0x80ff;		::TransparentRect( hDC, rc, clr, p->colorTrans );	}	else	{		RECT rcLevel=rc;		int m_nHeight=rcLevel.bottom-rcLevel.top;		rcLevel.top=rcLevel.bottom-(int)((m_nHeight/(p->WorkMax-p->WorkMin))*dValue);		::TransparentRect( hDC, rcLevel, clr, p->colorTrans );		::TransparentRect( hDC, rc, p->colorBkg, p->colorTrans );	}}// Функция отображенияint PaintDataSH(DefinePaint)  {  QueueP(Queue_DataSH);  //  if (q.m_pSocket->IsConnected())  {	  switch (p->dataType)	  {			case DataBool:q.m_pSocket->GetParam(p->szName, p->szParam,p->bValue);break;			case DataInt:q.m_pSocket->GetParam(p->szName, p->szParam,p->nValue);break;			case DataDouble:q.m_pSocket->GetParam(p->szName, p->szParam,p->dValue);break;	  }  }  if (Version==MFCU_2_AGCC)  {	  if (lstrcmp(p->szParam,"Заданное давление(и)")==0)		  p->dValue=p->dValue/10.2;  }  if (p->dataType==DataDouble)  {	if ( p->nType == 0 ) DrawValue( hDC, p, p->dValue, "%" );	if ( p->nType == 1 ) DrawValue( hDC, p, p->dValue, "" );	if ( p->nType == 2 ) DrawValue( hDC, p, p->dValue*100, "%" );	if ( p->nType == 4 )		PaintTransparentLevel(hDC, p, p->mRect,p->colorLevel, p->dValue, false);    if ( p->nType == 5 )	{		char szText[64] = "\0";		if (p->dValue<0.05)			p->gasType=GasLiquiedLiquied;		else			if (p->dValue>0.95)				p->gasType=GasLiquiedGas;		if (p->gasType==GasLiquiedLiquied)		{			lstrcpy(szText,"Идет жидкость");			::DrawText( hDC, szText, lstrlen(szText), &p->mRect, DT_SINGLELINE|DT_VCENTER|DT_CENTER );		}		else		if (p->gasType==GasLiquiedGas)		{			lstrcpy(szText,"Идет газ");			::DrawText( hDC, szText, lstrlen(szText), &p->mRect, DT_SINGLELINE|DT_VCENTER|DT_CENTER );		}	}	if ( p->nType == 6 )	{		char szText[64] = "\0";		if (p->dValue<=0.1)			p->gasType=GasLiquiedLiquied;		else			if (p->dValue>=0.9)				p->gasType=GasLiquiedGas;			else				p->gasType=GasLiquiedGasLiquied;		if (lstrcmp(p->szView,"")!=0)		{             double dValueView=0;			 q.m_pSocket->GetParam(p->szName, p->szView,dValueView);             if (dValueView==0)				 p->gasType=GasLiquiedNone;		}		if (p->gasType==GasLiquiedLiquied)		{			lstrcpy(szText,"жидкость");			::DrawText( hDC, szText, lstrlen(szText), &p->mRect, DT_SINGLELINE|DT_VCENTER|DT_CENTER );		}		else		if (p->gasType==GasLiquiedGas)		{			lstrcpy(szText,"газ");			::DrawText( hDC, szText, lstrlen(szText), &p->mRect, DT_SINGLELINE|DT_VCENTER|DT_CENTER );		}		else		if (p->gasType==GasLiquiedGasLiquied)		{			lstrcpy(szText,"газ/жидкость");			::DrawText( hDC, szText, lstrlen(szText), &p->mRect, DT_SINGLELINE|DT_VCENTER|DT_CENTER );		}	}  }  //  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddDataSH(DefineTegs)  {  //  AddQueueEx(Queue_DataSH);  //  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintDataSH;  p->bValue=false;  p->nValue=0;  p->dValue=0;  p->dataType=DataDouble;  char szShift[64] = "\0";  p->nType=0;  p->colorLevel=0;  p->WorkMin=0;  p->WorkMax=100;  p->gasType=GasLiquiedNone;  lstrcpy(p->szView,"");  //  STegObj obj[] =    {    { 'I', "type" , &p->nType },	{ 'S', "shift", szShift, 63},	{ 'A', "colorLevel" , &p->colorLevel },    { 'A', "colorBkg" , &p->colorBkg },	{ 'A', "colorTrans" , &p->colorTrans },    { 'D', "min" ,  &p->WorkMin },    { 'D', "max" ,  &p->WorkMax },	{ 'S', "view", p->szView, 63},    // Дополнительная информация    EXT_QUEUE    };  //  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  lstrcpy(p->szName,teg->value);  lstrcpy(p->szParam,szShift);  if (lstrcmp(p->szName,".")==0)  {	  int nActive=def.GetActiveObjSocket();	  const char* name = def.GetModelName(nActive);	  lstrcpy(p->szName,name);  }  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~